package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.world.entity.player.Inventory;import net.minecraft.network.chat.Component;
public class Ndc01Screen extends AbstractContainerScreen<Ndc01Menu>{
 private Button inventory;
 public Ndc01Screen(Ndc01Menu menu,Inventory inv,Component title){super(menu,inv,title);imageWidth=320;imageHeight=258;}
 private void action(int n){if(minecraft.gameMode!=null)minecraft.gameMode.handleInventoryButtonClick(menu.containerId,n);}
 @Override protected void init(){super.init();addRenderableWidget(Button.builder(Component.literal("Fleet / Return"),b->action(25)).bounds(leftPos+232,topPos+5,80,14).build());for(int i=0;i<18;i++){final int slot=i;addRenderableWidget(Button.builder(Component.literal(String.format(java.util.Locale.ROOT,"%02d",i+1)),b->action(slot)).bounds(leftPos+35+(i%3)*44,topPos+33+(i/3)*20,23,18).build());}String[]names={"Link bay to monitor","Next radar target","Launch & Fly","Return to ship control"};for(int i=0;i<4;i++){final int a=20+i;addRenderableWidget(Button.builder(Component.literal(names[i]),b->action(a)).bounds(leftPos+151,topPos+32+i*24,159,20).build());}inventory=addRenderableWidget(Button.builder(Component.literal("Drone Inventory"),b->action(24)).bounds(leftPos+151,topPos+128,159,20).build());}
 @Override public void containerTick(){super.containerTick();inventory.active=menu.inventoryAvailable();inventory.setTooltip(net.minecraft.client.gui.components.Tooltip.create(Component.literal(menu.inventoryHint())));}
 @Override protected void renderBg(GuiGraphics g,float p,int x,int y){g.fill(leftPos,topPos,leftPos+imageWidth,topPos+imageHeight,0xf51a2525);for(var slot:menu.slots){g.fill(leftPos+slot.x-1,topPos+slot.y-1,leftPos+slot.x+17,topPos+slot.y+17,0xff708078);g.fill(leftPos+slot.x,topPos+slot.y,leftPos+slot.x+16,topPos+slot.y+16,0xff202a29);}}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){g.drawString(font,"MAGURA MV11 / NDC-01",10,9,0xe1eadd,false);g.drawString(font,"FE "+menu.energy()+" / "+menu.capacity()+" | 18 bays",10,22,0x98d5b0,false);g.drawString(font,"Bow ↓ / Port → Stbd",10,155,0xadbab4,false);int s=menu.selected();g.drawString(font,"Bay: "+(s<0?"Select 01–18":String.format(java.util.Locale.ROOT,"%02d",s+1)),10,169,0xffffff,false);if(s>=0){var item=menu.getSlot(s).getItem();String name=item.isEmpty()?"Empty":item.getHoverName().getString();g.drawString(font,font.plainSubstrByWidth(name,130),10,180,0xffffff,false);g.drawString(font,Component.translatable("ndc01.state."+menu.state(s)),10,191,0x98d5b0,false);}var target=minecraft.level==null?null:minecraft.level.getEntity(menu.target());g.drawString(font,font.plainSubstrByWidth("Target: "+(target==null?"none":target.getName().getString()),158),151,155,0xd2cfaa,false);g.drawWordWrap(font,Component.translatable("ndc01.reason."+menu.reason()),10,220,135,0xe7c38c);g.drawString(font,font.plainSubstrByWidth("Drone FE: "+menu.droneEnergy()/1000+"k / "+menu.droneCapacity()/1000+"k",135),10,204,0xa7d9b1,false);for(int i=0;i<18;i++)if(menu.state(i)==1||menu.state(i)==3||menu.state(i)==6)g.fill(14+(i%3)*44,33+(i/3)*20,17+(i%3)*44,51+(i/3)*20,menu.state(i)==6?0xffff6840:0xffe5c85b);}
 @Override public void render(GuiGraphics g,int x,int y,float partial){renderBackground(g,x,y,partial);super.render(g,x,y,partial);renderTooltip(g,x,y);if(hoveredSlot!=null&&hoveredSlot.index<18){int s=hoveredSlot.index;g.renderTooltip(font,Component.literal("Bay "+(s+1)+": "+Component.translatable("ndc01.state."+menu.state(s)).getString()),x,y);}}
}
